INSERT INTO `medicines` VALUES (1,'0.1% triamcinolone acetonide Lotion 30 ml bottle','bottle','1. เป็นโลชั่น ชนิด สำหรับใช้ภายนอก\n2. ประกอบด้วยตัวยา 0.1% triamcinolone acetonide Lotion 30 ml bottle\n3. บรรจุในภาชนะปิดสนิท หรือภาชนะบรรจุภัณฑ์เฉพาะของยานั้นๆที่ได้รับมาตราฐาน\n4. ฉลาก\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์','2026-06-11 07:54:10'),(2,'0.5% Tetracain HCl eye Drop  bottle','bottle','1. เป็นยาหยอดตา ชนิด ปราศจาคเชื้อ สำหรับใช้เฉพาะที่\n2. ประกอบด้วยตัวยา 0.5% Tetracain HCl eye Drop  bottle\n3. บรรจุในภาชนะปิดสนิท หรือภาชนะบรรจุภัณฑ์เฉพาะของยานั้นๆที่ได้รับมาตราฐาน\n4. ฉลาก\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์','2026-06-11 07:54:10'),(3,'Acyclovir 400 mg tablet','tablet','1. เป็นยาเม็ด หรือ แคปซูล ชนิด รับประทาน\n2. ประกอบด้วยตัวยา Acyclovir 400 mg tablet\n3. บรรจุในภาชนะปิดสนิท หรือภาชนะบรรจุภัณฑ์เฉพาะของยานั้นๆที่ได้รับมาตราฐาน\n4. ฉลาก\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์','2026-06-11 07:54:10'),(4,'Acyclovir 5% cream 1 g sachet','sachet','1. เป็นยาครีม ชนิด ยาทาภายนอก\n2. ประกอบด้วยตัวยา Acyclovir 5% cream 1 g sachet\n3. บรรจุในภาชนะปิดสนิท หรือภาชนะบรรจุภัณฑ์เฉพาะของยานั้นๆที่ได้รับมาตราฐาน\n4. ฉลาก\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์','2026-06-11 07:54:10'),(5,'Adrenaline 1mg/ml inj ampoule','ampoule','1. เป็นยาฉีด ชนิด ปราศจาคเชื้อ\n2. ประกอบด้วยตัวยา Adrenaline 1mg/ml inj ampoule\n3. บรรจุในภาชนะปิดสนิท หรือภาชนะบรรจุภัณฑ์เฉพาะของยานั้นๆที่ได้รับมาตราฐาน\n4. ฉลาก\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์','2026-06-11 07:54:10'),(6,'Albendazole 200 mg tablet','tablet','1. เป็นยาเม็ด หรือ แคปซูล ชนิด รับประทาน\n2. ประกอบด้วย