INSERT INTO `price_source_drafts` VALUES (2,'ราคาที่ได้จากสืบ 3 ร้าน','แหล่งที่มาราคากลาง อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) 0405.2/ว 119 ลงวันที่ 12 มีนาคม 2562 สืบราคาไม่ต่ำกว่า 3 ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ 25 สิงหาคม 2568 (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน 1 ร้านได้แก่ บริษัท ชุมชนเภสัชกรรม จำกัด (มหาชน) รายละเอียด ดังนี้','2026-04-21 06:50:40');
/*!40000 ALTER TABLE `price_source_drafts` ENABLE KEYS */;
