INSERT INTO `procurement_documents` VALUES (53,5,'principle_approval','๑๘๐','๑๑ มีนาคม ๒๕๖๙','[]','2026-04-29 04:07:13','2026-04-29 04:07:13'),(54,5,'committee_scope_invitation','๑๘๑','๑๒ มีนาคม ๒๕๖๙','{\"signer_name\": \"นายสุวิท วรเจริญ\", \"meeting_date\": \"๑๘ มีนาคม ๒๕๖๘\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง ปฏิบัติราชการแทน                      นายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 04:08:45','2026-04-29 04:09:07'),(56,5,'tor_company_purchase','','','{\"history_id\": 28}','2026-04-29 04:13:19','2026-04-29 04:13:19'),(57,5,'meeting_report','','','{\"items\": [{\"name\": \"Levothyroxine 0.1 mg\", \"unit\": \"tablet\", \"quantity\": 10000, \"offer_price\": 0.35, \"offer_total\": 3500, \"reference_price\": 0.63}, {\"name\": \"Propylthiouracil 50 mg\", \"unit\": \"tablet\", \"quantity\": 3000, \"offer_price\": 0.5, \"offer_total\": 1500, \"reference_price\": 0.54}, {\"name\": \"Methimazole 5 mg\", \"unit\": \"tablet\", \"quantity\": 5000, \"offer_price\": 0.55, \"offer_total\": 2750, \"reference_price\": 0.7}], \"saved_at\": \"2026-04-29T04:24:37+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๑๘๑ ลงวันที่ ๑๒ มีนาคม ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๓ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท บริษัท เอสพีเอส จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 28, \"references\": [{\"doc_date\": \"๑๑ มีนาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๑๘๐\"}, {\"doc_date\": \"๑๒ มีนาคม ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๑๘๑\"}, {\"title\": \"TOR จัดซื้อยา ๓ รายการ - 2026-04-29 04:13\", \"created_at\": \"2026-04-29 11:13:19\", \"history_id\": 28, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๑๘ มีนาคม ๒๕๖๘\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 04:24:37','2026-04-29 04:24:37'),(58,6,'principle_approval','๑๑๕','๒๖ กุมภาพันธ์ ๒๕๖๙','[]','2026-04-29 04:35:44','2026-04-29 04:35:44'),(59,6,'committee_scope_invitation','๑๑๗','๒๗ กุมภาพันธ์ ๒๕๖๙','{\"signer_name\": \"นายสุวิท วรเจริญ\", \"meeting_date\": \"๒ มีนาคม ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"ปฏิบัติราชการแทนนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 04:36:59','2026-04-29 04:36:59'),(60,6,'tor_company_purchase','','','{\"history_id\": 29}','2026-04-29 04:38:19','2026-04-29 04:38:19'),(61,6,'meeting_report','','','{\"items\": [{\"name\": \"rabies vaccine 2.5IU .inj\", \"unit\": \"vial\", \"quantity\": 150, \"offer_price\": 240.97, \"offer_total\": 36145.5, \"reference_price\": 315.65}], \"saved_at\": \"2026-04-29T04:39:32+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๑๑๗ ลงวันที่ ๒๗ กุมภาพันธ์ ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๑ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นางสาวธนัชพร พัฒนปาลี\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท ไบโอวาลิส จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวธนัชพร พัฒนปาลี\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 29, \"references\": [{\"doc_date\": \"๒๖ กุมภาพันธ์ ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๑๑๕\"}, {\"doc_date\": \"๒๗ กุมภาพันธ์ ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๑๑๗\"}, {\"title\": \"TOR จัดซื้อยา ๑ รายการ - 2026-04-29 04:38\", \"created_at\": \"2026-04-29 11:38:19\", \"history_id\": 29, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๒ มีนาคม ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 04:39:32','2026-04-29 04:39:32'),(62,7,'principle_approval','๒๓๑','๒๖ มีนาคม ๒๕๖๙','[]','2026-04-29 04:46:19','2026-04-29 04:46:19'),(63,7,'committee_scope_invitation','๒๓๔','๒๗ มีนาคม ๒๕๖๙','{\"signer_name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"meeting_date\": \"\", \"meeting_time\": \"\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง ปฏิบัติราชการแทน  นายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 04:47:03','2026-04-29 04:47:03'),(64,7,'tor_company_purchase','','','{\"history_id\": 30}','2026-04-29 04:48:12','2026-04-29 04:48:12'),(65,7,'meeting_report','','','{\"items\": [{\"name\": \"Atorvastatin 40 mg\", \"unit\": \"tablet\", \"quantity\": 40000, \"offer_price\": 1.14, \"offer_total\": 45599.99999999999, \"reference_price\": 2.5}], \"saved_at\": \"2026-04-29T04:48:52+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๓๔ ลงวันที่ ๒๗ มีนาคม ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๑ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท ทีแมน ฟาร์มาซูติคอล จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 30, \"references\": [{\"doc_date\": \"๒๖ มีนาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๓๑\"}, {\"doc_date\": \"๒๗ มีนาคม ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๓๔\"}, {\"title\": \"TOR จัดซื้อยา ๑ รายการ - 2026-04-29 04:48\", \"created_at\": \"2026-04-29 11:48:12\", \"history_id\": 30, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"\", \"meeting_time\": \"\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 04:48:52','2026-04-29 04:48:52'),(66,8,'principle_approval','๒๓๕','๒๗ มีนาคม ๒๕๖๙','[]','2026-04-29 04:58:03','2026-04-29 04:58:03'),(67,8,'committee_scope_invitation','๒๓๗','๓๐ มีนาคม ๒๕๖๙','{\"signer_name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"meeting_date\": \"๑ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๐๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง ปฏิบัติราชการแทนนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 05:00:39','2026-04-29 05:00:39'),(68,8,'tor_company_purchase','','','{\"history_id\": 31}','2026-04-29 05:09:43','2026-04-29 05:09:43'),(69,8,'meeting_report','','','{\"items\": [{\"name\": \"Sodium bicarbonate 300 mg\", \"unit\": \"tablet\", \"quantity\": 150000, \"offer_price\": 0.09, \"offer_total\": 13500, \"reference_price\": 0.09}, {\"name\": \"Vitamin C 100 mg\", \"unit\": \"เม็ด\", \"quantity\": 8000, \"offer_price\": 0.16, \"offer_total\": 1280, \"reference_price\": 0.16}, {\"name\": \"Dicloxacilline 62.5 mg/5ml\", \"unit\": \"ขวด\", \"quantity\": 50, \"offer_price\": 22, \"offer_total\": 1100, \"reference_price\": 22.47}], \"saved_at\": \"2026-04-29T05:10:20+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๓๗ ลงวันที่ ๓๐ มีนาคม ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๓ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท บริษัท พรีเมด ฟาร์มา จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๐๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 31, \"references\": [{\"doc_date\": \"๒๗ มีนาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๓๕\"}, {\"doc_date\": \"๓๐ มีนาคม ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๓๗\"}, {\"title\": \"TOR จัดซื้อยา ๓ รายการ - 2026-04-29 05:09\", \"created_at\": \"2026-04-29 12:09:43\", \"history_id\": 31, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๑ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๐๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 05:10:20','2026-04-29 05:10:20'),(70,9,'principle_approval','๒๓๖','๓๐ มีนาคม ๒๕๖๙','[]','2026-04-29 06:41:02','2026-04-29 06:41:02'),(71,9,'committee_scope_invitation','๒๓๙','๓๑ มีนาคม ๒๕๖๙','{\"signer_name\": \"นายสุวิท วรเจริญ\", \"meeting_date\": \"๓ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง ปฏิบัติราชการแทน \\r\\nนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 06:42:23','2026-05-03 04:04:50'),(72,9,'tor_company_purchase','','','{\"history_id\": 32}','2026-04-29 06:46:47','2026-05-27 03:22:21'),(73,9,'meeting_report','','','{\"items\": [{\"name\": \"Haloperidol Decanoate 50mg/ml .inj\", \"unit\": \"Amp\", \"quantity\": 20, \"offer_price\": 63, \"offer_total\": 1260, \"reference_price\": 63.13}, {\"name\": \"Fluphenazine Decanoate 25mg/ml .inj\", \"unit\": \"Amp\", \"quantity\": 50, \"offer_price\": 29, \"offer_total\": 1450, \"reference_price\": 29.54}, {\"name\": \"Phenytoin 100 mg\", \"unit\": \"capsule\", \"quantity\": 4000, \"offer_price\": 0.44, \"offer_total\": 1760, \"reference_price\": 0.49}], \"saved_at\": \"2026-04-29T06:47:40+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๓๙ ลงวันที่ ๓๑ มีนาคม ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๓ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท แอตแลนติค ฟาร์มาซูติคอล จำกัด  รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๔\", \"content\": \"ไม่มี\", \"speaker\": \"\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 32, \"references\": [{\"doc_date\": \"๓๐ มีนาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๓๖\"}, {\"doc_date\": \"๓๑ มีนาคม ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๓๙\"}, {\"title\": \"TOR จัดซื้อยา ๓ รายการ - 2026-04-29 06:46\", \"created_at\": \"2026-04-29 13:46:47\", \"history_id\": 32, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๓ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 06:47:40','2026-04-29 06:47:40'),(77,11,'principle_approval','๒๓๓','๒๗ มีนาคม ๒๕๖๙','[]','2026-04-29 07:13:21','2026-04-29 07:13:21'),(78,11,'committee_scope_invitation','๒๔๑','๑ เมษายน ๒๕๖๙','{\"signer_name\": \"นายสุวิท วรเจริญ\", \"meeting_date\": \"๘ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง \\r\\nปฏิบัติราชการแทนนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-04-29 07:13:59','2026-06-11 07:57:28'),(79,11,'tor_company_purchase','','','{\"history_id\": 33}','2026-04-29 07:16:39','2026-04-29 07:16:39'),(80,11,'meeting_report','','','{\"items\": [{\"name\": \"Terramycin Oint 3.5Gm\", \"unit\": \"Tube\", \"quantity\": 1, \"offer_price\": 2182.8, \"offer_total\": 2182.8, \"reference_price\": 2183.04}], \"saved_at\": \"2026-04-29T07:17:16+00:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๔๑ ลงวันที่ ๑ เมษายน ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๑ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท บริษัท ซิลลิค ฟาร์มา รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๔\", \"content\": \"ไม่มี\", \"speaker\": \"\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 33, \"references\": [{\"doc_date\": \"๒๗ มีนาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๓๓\"}, {\"doc_date\": \"๑ เมษายน ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๔๑\"}, {\"title\": \"TOR จัดซื้อยา ๑ รายการ - 2026-04-29 07:16\", \"created_at\": \"2026-04-29 14:16:39\", \"history_id\": 33, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๘ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-04-29 07:17:16','2026-04-29 07:17:16'),(86,12,'principle_approval','๒๕๓','๒ เมษายน ๒๕๖๙','[]','2026-05-27 02:36:07','2026-05-27 02:36:07'),(87,12,'committee_scope_invitation','๒๖๐','๓ เมษายน ๒๕๖๙','{\"signer_name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"meeting_date\": \"๙ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"เภสัชกรปฏิบัติการ\", \"signer_signature\": \"\"}','2026-05-27 02:38:27','2026-05-27 02:38:27'),(88,12,'tor_company_purchase','','','{\"history_id\": 34}','2026-05-27 02:49:47','2026-05-27 02:49:47'),(89,12,'meeting_report','','','{\"items\": [{\"name\": \"Fluticasone propionate 125mcg+salmeterol 25mcg INH 120 Dose actuation\", \"unit\": \"Botte\", \"quantity\": 50, \"offer_price\": 114.49, \"offer_total\": 5724.5, \"reference_price\": 299.6}, {\"name\": \"Cetirizine 10 mg\", \"unit\": \"tablet\", \"quantity\": 20, \"offer_price\": 135.89, \"offer_total\": 2717.7999999999997, \"reference_price\": 600}, {\"name\": \"Ibuprofen 400 mg\", \"unit\": \"tablet\", \"quantity\": 12, \"offer_price\": 203.3, \"offer_total\": 2439.6000000000004, \"reference_price\": 400}], \"saved_at\": \"2026-05-26T23:00:00-04:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๖๐ ลงวันที่ ๓ เมษายน ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๓ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท ดีทแฮล์ม เคลเลอร์ โลจิสติกส์ จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๔\", \"content\": \"ไม่มี\", \"speaker\": \"\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 34, \"references\": [{\"doc_date\": \"๒ เมษายน ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๕๓\"}, {\"doc_date\": \"๓ เมษายน ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๖๐\"}, {\"title\": \"TOR จัดซื้อยา ๓ รายการ - 2026-05-26 22:49\", \"created_at\": \"2026-05-26 19:49:47\", \"history_id\": 34, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๙ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๓ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-05-27 03:00:01','2026-05-27 03:00:01'),(97,15,'principle_approval','๒๓๓','๙ มิถุนายน ๒๕๖๙','[]','2026-06-12 02:23:12','2026-06-12 02:23:12'),(98,15,'committee_scope_invitation','๒๓๙','๑๐ มิถุนายน ๒๕๖๙','{\"signer_name\": \"นายสุวิทย์ วรเจริญ\", \"meeting_date\": \"๘ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๐๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง\\r\\nปฏิบัติราชการแทนนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-06-12 02:23:33','2026-06-12 02:23:33'),(99,15,'tor_company_purchase','','','{\"history_id\": 35}','2026-06-12 02:24:13','2026-06-12 02:24:13'),(100,15,'meeting_report','','','{\"items\": [{\"name\": \"PCEC(Purified Chick-Embryo Cell Rabies Vaccine) inj vial\", \"unit\": \"vial\", \"quantity\": 40000, \"offer_price\": 288, \"offer_total\": 11520000, \"reference_price\": 294.25}], \"saved_at\": \"2026-06-17T03:33:13-04:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๒๓๙ ลงวันที่ ๑๐ มิถุนายน ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๑ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นาายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท มาสุ จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นาายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๐๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 35, \"references\": [{\"doc_date\": \"๙ มิถุนายน ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๒๓๓\"}, {\"doc_date\": \"๑๐ มิถุนายน ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๒๓๙\"}, {\"title\": \"TOR จัดซื้อยา ๑ รายการ - 2026-06-11 22:24\", \"created_at\": \"2026-06-11 19:24:13\", \"history_id\": 35, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๘ เมษายน ๒๕๖๙\", \"meeting_time\": \"๐๙.๐๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดราคากลาง\"}','2026-06-12 02:24:54','2026-06-17 07:33:13'),(102,16,'principle_approval','๕๑๑','๒๕ พฤษภาคม ๒๕๖๙','[]','2026-06-24 02:37:32','2026-06-24 02:37:32'),(103,16,'committee_scope_invitation','๕๒๔','๒๗ พฤษภาคม ๒๕๖๙','{\"signer_name\": \"นายสุวิทย์ วรเจริญ\", \"meeting_date\": \"๒๙ พฤษภาคม ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"signer_position\": \"ผู้อำนวยการ รพ.สต.บ้านสันโค้ง\\r\\nปฏิบัติราชการแทนนายกองค์การบริหารส่วนจังหวัดเชียงใหม่\", \"signer_signature\": \"\"}','2026-06-24 02:38:25','2026-06-24 02:38:25'),(104,16,'tor_company_purchase','','','{\"history_id\": 36}','2026-06-24 02:40:11','2026-06-24 02:40:11'),(105,16,'meeting_report','','','{\"items\": [{\"name\": \"Theophylline 200 mg tablet\", \"unit\": \"tablet\", \"quantity\": 3000, \"offer_price\": 1.8, \"offer_total\": 5400, \"reference_price\": 1.8}], \"saved_at\": \"2026-06-23T22:41:58-04:00\", \"speeches\": [{\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"ตามที่ได้เชิญคณะกรรมการฯ เข้าร่วมประชุมในครั้งนี้ สืบเนื่องจากการที่ได้รับแต่งตั้งเป็นคณะกรรมการกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลาง เพื่อจัดซื้อยา ใช้สนับสนุนการให้บริการรักษาประชาชน ของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ ตามบันทึกข้อความโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ที่ ๕๒๔ ลงวันที่ ๒๗ พฤษภาคม ๒๕๖๙ เรื่อง แจ้งคำสั่งและเชิญประชุมแต่งตั้งคณะกรรมการร่างขอบเขตและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ประจำปีงบประมาณ พ.ศ. ๒๕๖๙ โดยให้มีหน้าที่พิจารณากลั่นกรองและกำหนดรายละเอียดคุณลักษณะเฉพาะและราคากลางของยาที่จะจัดซื้อ ให้ตรงตามวัตถุประสงค์และตามระเบียบราชการ ให้เกิดความคุ้มค่ามากที่สุด เพื่อให้การดำเนินงานตามอำนาจหน้าที่ของคณะกรรมการฯ เป็นไปด้วยความเรียบร้อย จึงได้เชิญท่านเข้าร่วมประชุมในครั้งนี้\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๑\", \"content\": \"รับทราบ\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๒\", \"content\": \"๑. ระเบียบกระทรวงมหาดไทยว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานขององค์กรปกครองส่วนท้องถิ่น พ.ศ. ๒๕๖๒ หมวดที่ ๒ ค่าใช้สอย ข้อ ๑๑ ค่าใช้จ่ายที่เป็นค่าใช้สอยมีดังต่อไปนี้ (๒) ค่าจ้างเอกชนดำเนินงานขององค์กรปกครองส่วนท้องถิ่น\\r\\n๒. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐\\r\\n๓. ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. ๒๕๖๐ หมวด ๒ ส่วนที่ ๒ กระบวนการซื้อหรือจ้าง ข้อ ๒๑ ในการซื้อหรือจ้างที่มิใช่การจ้างก่อสร้าง ให้หัวหน้าหน่วยงานของรัฐแต่งตั้งคณะกรรมการขึ้นมาคณะหนึ่ง หรือจะให้เจ้าหน้าที่หรือบุคคลใดบุคคลหนึ่งรับผิดชอบในการจัดทำร่างขอบเขตงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุที่จะซื้อหรือจ้าง รวมทั้งกำหนดหลักเกณฑ์การพิจารณาคัดเลือกข้อเสนอด้วย\\r\\n๔. หนังสือกรมส่งเสริมการปกครองส่วนท้องถิ่น ที่ มท ๐๘๐๘.๒/ว ๑๐๙๕ ลงวันที่ ๒๘ พฤษภาคม ๒๕๖๔ เรื่อง รูปแบบและการจำแนกประเภทรายรับ-รายจ่าย งบประมาณรายจ่ายประจำปีขององค์กรปกครองส่วนท้องถิ่น\\r\\n๕. ระเบียบกระทรวงมหาดไทย ว่าด้วยเงินบำรุงโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น (ฉบับที่ ๒) พ.ศ. ๒๕๖๑ (๑) ค่าใช้สอย รายจ่ายเพื่อให้ได้มาซึ่งบริการ\\r\\n๖. หนังสือกระทรวงมหาดไทย ด่วนที่สุด ที่ มท ๐๘๐๘.๒/ว ๗๓๐๓ ลงวันที่ ๓๐ กันยายน ๒๕๖๕ เรื่อง ซักซ้อมแนวทางการปฏิบัติงานด้านการเงินการคลังของโรงพยาบาลและหน่วยบริการสาธารณสุขขององค์กรปกครองส่วนท้องถิ่น\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"ขอให้คณะกรรมการร่วมกันพิจารณารายละเอียดคุณลักษณะเฉพาะและกำหนดราคากลาง เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ ดังรายการต่อไปนี้\\r\\n[medicine_items]\\r\\nเพื่อเป็นไปตามระเบียบพัสดุอย่างรอบคอบ เพื่อใช้สนับสนุนการให้บริการรักษาประชาชนของหน่วยบริการประจำโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"speaker\": \"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nประธานกรรมการ\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดรายละเอียดคุณลักษณะเฉพาะ ดังนี้\\r\\n๑. เป็นยาในบัญชียาหลักแห่งชาติที่องค์การเภสัชกรรมมีจัดจำหน่าย\\r\\n๒. ส่วนประกอบยาแต่ละรายการตามชื่อยาสามัญทางยา ที่กำหนด ๑ รายการ\\r\\n๓. บรรจุภัณฑ์สามารถบรรจุในขวดปราศจากเชื้อ ภาชนะปิดสนิท แผง สตริป หรือบรรจุภัณฑ์ที่ผ่านการรับรองมาตรฐาน\\r\\n๔. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบสำคัญและความแรง วันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยาไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\r\\n- กรณีที่บรรจุในขวด หลอด แผง ต้องระบุวัน เดือน ปีที่ยาหมดอายุ และเลขที่ผลิตไว้อย่างชัดเจน\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากการพิจารณาขอบเขตงานและราคากลางที่อ้างอิงราคากลาง อ้างอิงตาระเบียบการจัดซื้อจัดจ้าง ตามกฎกระทรวงกำหนดพัสดุและวิธีการจัดซื้อจัดจ้างพัสดุที่รัฐต้องการส่งเสริมหรือสนับสนุน พ.ศ.๒๕๖๓ ข้อ ๑๕ (๒) ยาในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยา ซึ่งองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ได้ผลิตออกจำหน่ายแล้ว และข้อ ๑๗ ให้หน่วยงานของรัฐจัดซื้อพัสดุตามข้อ ๑๕ (๒) โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรม หรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มีใช่ยาจากผู้ขายรายอื่นได้ หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า ประกอบกับหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ ข้อ ๓.๑.๑ ให้หน่วยงานของรัฐจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาซึ่งองค์การเภสัชกรรมหรือสภากาชาดไทยได้ผลิตออกจำหน่ายแล้ว โดยวิธีเฉพาะเจาะจงจากองค์การเภสัชกรรมหรือสภากาชาดไทย เว้นแต่หน่วยงานในสังกัดกระทรวงกลาโหมให้จัดซื้อจากโรงงานเภสัชกรรมทหารสำหรับหน่วยงานในสังกัดสำนักงานตำรวจแห่งชาติจะซื้อจากองค์การเภสัชกรรมหรือโรงงานเภสัชกรรมทหารก็ได้ ทั้งนี้ หน่วยงานของรัฐสามารถจัดซื้อยาที่อยู่ในบัญชียาหลักแห่งชาติหรือเวชภัณฑ์ที่มิใช่ยาจากผู้ขายรายอื่นได้หากองค์การเภสัชกรรม สภากาชาดไทย หรือโรงงานเภสัชกรรมทหาร ไม่สามารถผลิตออกจำหน่ายให้แก่หน่วยงานของรัฐได้ทันกำหนดตามที่หน่วยงานของรัฐได้แจ้งแผนประจำปีล่วงหน้า\", \"speaker\": \"นางสาวพรไพลิน แก้วแสนซาว\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"จากประวัติการจัดซื้อจัดจ้างย้อนหลัง ๒ ปี และข้อมูลราคาที่มีอยู่ เห็นควรเสนอจัดซื้อจัดจ้างตามระเบียบ โดยอ้างอิงจากการจัดซื้อจัดจ้างตามระเบียบ โดยสามารถอ้างอิงราคาที่เคยซื้อย้อนหลัง ๒ ปี หรือสืบราคาร้านค้าเพื่อใช้ประกอบการกำหนดราคากลางไม่น้อยกว่า ๓ ร้านตามระยะเวลาที่กำหนดให้เสนอราคา\", \"speaker\": \"นายไชยา บุญทานุช\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๓\", \"content\": \"เห็นชอบกำหนดราคากลาง โดยใช้ราคากลางจาก อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) ๐๔๐๕.๒/ว ๑๑๙ ลงวันที่ ๑๒ มีนาคม ๒๕๖๒ สืบราคาไม่ต่ำกว่า ๓ ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ ๒๕ สิงหาคม ๒๕๖๘ (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน ๑ ร้านได้แก่ บริษัท ฟาร์มาดิกา จำกัด รายละเอียด ดังนี้\", \"speaker\": \"มติที่ประชุม\"}, {\"topic\": \"\", \"agenda\": \"ระเบียบวาระที่ ๔\", \"content\": \"\", \"speaker\": \"\"}], \"committee\": [{\"name\": \"นางสาวชุตติภัทร เงินอินต๊ะ\", \"role\": \"ประธานกรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นางสาวพรไพลิน แก้วแสนซาว\", \"role\": \"กรรมการ\", \"position\": \"เภสัชกรปฏิบัติการ\"}, {\"name\": \"นายไชยา บุญทานุช\", \"role\": \"กรรมการ\", \"position\": \"เจ้าพนักงานเภสัชกรรมปฏิบัติงาน\"}], \"open_time\": \"๐๙.๓๐ น.\", \"close_time\": \"๑๑.๐๐ น.\", \"history_id\": 36, \"references\": [{\"doc_date\": \"๒๕ พฤษภาคม ๒๕๖๙\", \"document_type\": \"principle_approval\", \"memo_no_suffix\": \"๕๑๑\"}, {\"doc_date\": \"๒๗ พฤษภาคม ๒๕๖๙\", \"document_type\": \"committee_scope_invitation\", \"memo_no_suffix\": \"๕๒๔\"}, {\"title\": \"TOR จัดซื้อยา ๑ รายการ - 2026-06-23 22:40\", \"created_at\": \"2026-06-23 19:40:11\", \"history_id\": 36, \"document_type\": \"tor_company_purchase\"}], \"absent_text\": \"ไม่มี\", \"fiscal_line\": \"ประจำปีงบประมาณ พ.ศ. ๒๕๖๙\", \"meeting_date\": \"๒๙ พฤษภาคม ๒๕๖๙\", \"meeting_time\": \"๐๙.๓๐ น.\", \"purpose_line\": \"เพื่อจัดหาการจัดซื้อยา จำนวน ๑ รายการ\", \"meeting_place\": \"ห้องประชุมโรงพยาบาลส่งเสริมสุขภาพตำบลบ้านสันโค้ง อำเภอสันกำแพง จังหวัดเชียงใหม่\", \"meeting_title\": \"รายงานการประชุมคณะกรรมการกำหนดร่างขอบเขตและกำหนดร