INSERT INTO `tor_histories` VALUES (28,5,'TOR จัดซื้อยา ๓ รายการ - 2026-04-29 04:13','[\"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nเภสัชกรปฏิบัติการ\\r\\nประธานกรรมการ\", \"นางสาวพรไพลิน แก้วแสนซาว\\r\\nเภสัชกรปฏิบัติการ\\r\\nกรรมการ\", \"นายไชยา บุญทานุช\\r\\nเจ้าพนักงานเภสัชกรรมปฏิบัติงาน\\r\\nกรรมการ\"]','[{\"name\": \"Levothyroxine 0.1 mg\", \"unit\": \"tablet\", \"quantity\": 10000, \"offer_price\": 0.35, \"offer_total\": 3500, \"specification\": \"1. เป็นยาเม็ดหรือแคปซูล ชนิดรับประทาน\\n2. ประกอบด้วยตัวยา  Levothyroxine 0.1 mgLevothyroxine 0.1 mg\\n3. บรรจุในแผงอลูมิเนียมฟอยล์ หรือ blister pack หรือภาชนะปิดสนิท \\n4. ฉลาก \\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง \\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\n- กรณีที่บรรจุในแผงอลูมิเนียมฟอยล์หรือ blister pack ต้องระบุวัน เดือน ปีที่ยาหมดอายุ, เลขที่ผลิตไว้ ชัดเจนบนแผง\", \"reference_price\": 0.63}, {\"name\": \"Propylthiouracil 50 mg\", \"unit\": \"tablet\", \"quantity\": 3000, \"offer_price\": 0.5, \"offer_total\": 1500, \"specification\": \"1. เป็นยาเม็ดหรือแคปซูล ชนิดรับประทาน\\n2. ประกอบด้วยตัวยา  Propylthiouracil 50 mgPropylthiouracil 50 mg\\n3. บรรจุในแผงอลูมิเนียมฟอยล์ หรือ blister pack หรือภาชนะปิดสนิท \\n4. ฉลาก \\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง \\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\n- กรณีที่บรรจุในแผงอลูมิเนียมฟอยล์หรือ blister pack ต้องระบุวัน เดือน ปีที่ยาหมดอายุ, เลขที่ผลิตไว้ ชัดเจนบนแผง\", \"reference_price\": 0.54}, {\"name\": \"Methimazole 5 mg\", \"unit\": \"tablet\", \"quantity\": 5000, \"offer_price\": 0.55, \"offer_total\": 2750, \"specification\": \"1. เป็นยาเม็ดหรือแคปซูล ชนิดรับประทาน\\n2. ประกอบด้วยตัวยา  Methimazole 5 mgMethimazole 5 mg\\n3. บรรจุในแผงอลูมิเนียมฟอยล์ หรือ blister pack หรือภาชนะปิดสนิท \\n4. ฉลาก \\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง \\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\\n- กรณีที่บรรจุในแผงอลูมิเนียมฟอยล์หรือ blister pack ต้องระบุวัน เดือน ปีที่ยาหมดอายุ, เลขที่ผลิตไว้ ชัดเจนบนแผง\", \"reference_price\": 0.7}]','แหล่งที่มาราคากลาง อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) 0405.2/ว 119 ลงวันที่ 12 มีนาคม 2562 สืบราคาไม่ต่ำกว่า 3 ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ 25 สิงหาคม 2568 (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน 1 ร้านได้แก่ บริษัท เอสพีเอส จำกัด รายละเอียด ดังนี้','2026-04-29 04:13:19','2026-04-29 04:13:19'),(29,6,'TOR จัดซื้อยา ๑ รายการ - 2026-04-29 04:38','[\"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nเภสัชกรปฏิบัติการ\\r\\nประธานกรรมการ\", \"นางสาวพรไพลิน แก้วแสนซาว\\r\\nเภสัชกรปฏิบัติการ\\r\\nกรรมการ\", \"นางสาวธนัชพร พัฒนปาลี\\r\\nเภสัชกรปฏิบัติการ\\r\\nกรรมการ\"]','[{\"name\": \"rabies vaccine 2.5IU .inj\", \"unit\": \"vial\", \"quantity\": 150, \"offer_price\": 240.97, \"offer_total\": 36145.5, \"specification\": \"1. เป็นยาฉีดปราศจากเชื้อ\\r\\n2. ประกอบด้วยตัวยา rabies vaccine 2.5IU .inj\\r\\n3. บรรจุใน amp vial หรือ ภาชนะปิดสนิท\\r\\n4. ฉลาก\\r\\n- ระบุชื่อยา ส่วนประกอบตัวยาสำคัญและความแรง\\r\\nวันผลิต วันสิ้นอายุ เลขที่ผลิต และเลขทะเบียนตำรับยา ไว้ชัดเจนปรากฏบนบรรจุภัณฑ์\", \"reference_price\": 315.65}]','แหล่งที่มาราคากลาง อ้างอิงตามหนังสือคณะกรรมการวินิจฉัยปัญหา จัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ กรมบัญชีกลาง ที่ กค (กวจ) 0405.2/ว 119 ลงวันที่ 12 มีนาคม 2562 สืบราคาไม่ต่ำกว่า 3 ร้าน โดยไม่เกินราคาที่ได้มาจากการคํานวณตามหลักเกณฑ์ที่คณะกรรมการราคากลางกำหนดจาก ประกาศคณะกรรมการพัฒนาระบบยาแห่งชาติ เรื่อง กำหนดราคากลางยา ลงวันที่ 25 สิงหาคม 2568 (ฉบับลงราชกิจจานุเบกษา) โดยมีผู้เสนอราคา จำนวน 1 ร้านได้แก่ บริษัท ไบโอวาลิส จำกัด รายละเอียด ดังนี้','2026-04-29 04:38:19','2026-04-29 04:38:19'),(30,7,'TOR จัดซื้อยา ๑ รายการ - 2026-04-29 04:48','[\"นางสาวชุตติภัทร เงินอินต๊ะ\\r\\nเภสัชกรปฏิบัติการ\\r\\nประธานกรรมการ\", \"นางสาวพรไพลิน แก้วแสนซาว\\r\\nเภสัชกรปฏิบัติการ\\r\\nกรรมการ\", \"นาายไชยา บุญทานุช\\r\